"""
Update the default user-agent version range used by yt-dlp.
"""

from __future__ import annotations

import argparse
import collections.abc
import os
import pathlib
import sys

from bot.command.common import (
    configure_export_options,
    configure_git_options,
    configure_github_options,
    configure_logging_options,
    configure_remote_target_options,
    configure_update_options,
    configure_update_pr_options,
    get_update_objects,
)
from bot.git import (
    Commit,
    GitError,
)
from bot.github import (
    RelativeBranch,
    get_gha_workflow_run_url,
    make_absolute_branch,
)
from bot.knowledge import (
    DEFAULT_HEAD_BRANCHES,
    DEFAULT_HEAD_OWNER,
    PULL_REQUEST_TEMPLATES,
    SERVICED_REPOS,
)
from bot.utils import (
    BaseAPICaller,
    BotError,
    SuccessMessage,
    VerificationError,
)

try:
    import yaml
except ImportError:
    yaml = None


UPDATE_NAME = 'user-agent'

DEFAULT_HEAD = RelativeBranch(owner=DEFAULT_HEAD_OWNER, branch=DEFAULT_HEAD_BRANCHES[UPDATE_NAME])

REPO = 'yt-dlp'

PREFIX = '    CHROME_MAJOR_VERSION_RANGE = '
TARGET_FILE = 'yt_dlp/utils/networking.py'
FLOOR_DIFF = 6


def configure_parser(parser: argparse.ArgumentParser):
    # NB: Do not use type=pathlib.Path in arg parser since it would convert empty arg to Path('.')
    parser.add_argument(
        'directory',
        metavar='DIRECTORY',
        nargs=argparse.OPTIONAL,
        help=(
            'local path to the root of the git working tree. '
            'if not provided and --clone is not used, it will default to the CWD ("."). '
            'if not provided and --clone is used, it will default to a temporary directory'
        ),
    )
    # Add common option groups
    configure_remote_target_options(
        parser,
        default_head_label=DEFAULT_HEAD.label,
    )
    configure_update_options(parser)
    configure_update_pr_options(parser)
    configure_git_options(parser)
    configure_github_options(parser)
    configure_export_options(parser)
    configure_logging_options(parser)


class _GoogleVersionHistoryAPICaller(BaseAPICaller):
    _API_BASE_URL = 'https://versionhistory.googleapis.com/'
    _NOTE_PREFIX = 'googleapis'

    def __init__(self, /, *, verbose: bool = False):
        super().__init__(
            base_url=self._API_BASE_URL,
            verbose=verbose,
            note_prefix=self._NOTE_PREFIX,
        )

    def get_latest_win_chrome_stable_release(self, /):
        return self._fetch_json(
            '/v1/chrome/platforms/win/channels/stable/versions/all/releases',
            query={'filter': 'endtime=none,fraction>=0.5', 'order_by': 'version desc'},
            headers=self.headers,
        )


def _get_old_range_line(module_text: str) -> str:
    for line in module_text.splitlines():
        if not line.startswith(PREFIX):
            continue
        return line

    raise BotError('unable to find user-agent range line')


def _get_old_user_agent_range(range_line: str) -> tuple[int, int]:
    floor, _, ceiling = range_line.removeprefix(PREFIX).removeprefix('(').removesuffix(')').partition(', ')
    return int(floor), int(ceiling)


def _get_new_user_agent_range(*, verbose: bool = False) -> tuple[int, int]:
    api = _GoogleVersionHistoryAPICaller(verbose=verbose)
    info = api.get_latest_win_chrome_stable_release()
    new_ceiling = int(info['releases'][0]['version'].partition('.')[0])
    return new_ceiling - FLOOR_DIFF, new_ceiling


def _replace_user_agent_range(
    module_text: str,
    range_line: str,
    new_range: tuple[int, int],
) -> collections.abc.Generator[str]:
    lines = module_text.splitlines(True)
    for line_number, line in enumerate(lines, start=1):
        if not line.startswith(PREFIX):
            yield line
            continue
        yield f'{PREFIX}{new_range}\n'
        yield from lines[line_number:]
        return


def update_user_agent_range(
    module_path: pathlib.Path,
    *,
    verify: bool = False,
    verbose: bool = False,
) -> tuple[tuple[int, int], tuple[int, int]]:
    module_text = module_path.read_text()
    range_line = _get_old_range_line(module_text)
    old_range = _get_old_user_agent_range(range_line)
    new_range = _get_new_user_agent_range(verbose=verbose)

    if old_range == new_range:
        raise SuccessMessage('user-agent version range is up-to-date')
    elif verify:
        raise VerificationError('update verification failed')

    with module_path.open(mode='w') as f:
        f.writelines(_replace_user_agent_range(module_text, range_line, new_range))

    return old_range, new_range


def _make_ua_pull_request_body_and_commit_message(
    old_range: tuple[int, int],
    new_range: tuple[int, int],
    author: str,
    *,
    include_serialized_data: bool = True,
) -> tuple[str, str]:
    body = f'Bump version range {"-".join(map(str, old_range))} => {"-".join(map(str, new_range))}'

    serialized_data_lines = [
        '---',
        yaml.safe_dump({UPDATE_NAME: {'old': old_range, 'new': new_range}}, sort_keys=False),
    ]

    return f'{body}\n', '\n\n'.join((
        f'[utils] `random_user_agent`: {body}',
        f'Authored by: {author}',
        *(serialized_data_lines if include_serialized_data else []),
    ))


def _get_original_user_agent_range(
    commits: list[Commit],
    old_range: tuple[int, int],
) -> tuple[int, int]:
    for commit in sorted(commits, key=lambda c: c.timestamp):
        parsed_yaml = yaml.safe_load(commit.message.partition('\n---\n')[2])
        if not parsed_yaml:
            continue

        update: dict[str, list[int]] = parsed_yaml.get(UPDATE_NAME, {})
        if not update or not update.get('old'):
            continue

        return update['old'][0], update['old'][1]

    return old_range


def _real_run(args: argparse.Namespace):
    if yaml is None:
        raise ImportError(
            'the pyyaml package (yaml library) is required for updates. '
            'install the "update" extra to fulfill the requirements'
        )

    repo_info = SERVICED_REPOS[REPO]
    _, pr, git, existing_commits = get_update_objects(
        args,
        make_absolute_branch(
            args.base_label or ':'.join((repo_info['owner'], repo_info['default_branch'])),
            REPO,
        ),
        make_absolute_branch(
            args.head_label or DEFAULT_HEAD.label,
            REPO,
        ),
    )

    starting_point = git.bot_rev_parse('HEAD')

    module_path = git.repo_path / TARGET_FILE
    if not module_path.is_file():
        raise BotError('unable to find yt_dlp.utils.networking module')

    old_range, new_range = update_user_agent_range(
        module_path,
        verify=args.verify,
        verbose=args.verbose,
    )

    pull_request_body, merge_commit_message = _make_ua_pull_request_body_and_commit_message(
        _get_original_user_agent_range(existing_commits, old_range),
        new_range,
        pr.head.owner,
        include_serialized_data=False,
    )

    pr.update_body(pull_request_body)
    pr.update_commit_message(merge_commit_message)

    if template := PULL_REQUEST_TEMPLATES.get(pr.base.repo):
        pr.append_to_body(template)

    if gha_url := get_gha_workflow_run_url():
        pr.append_to_body('---')
        pr.append_to_body(f'*This pull request is the product of [this GitHub Actions workflow run]({gha_url}).*')

    git.bot_commit(
        _make_ua_pull_request_body_and_commit_message(old_range, new_range, pr.head.owner)[1],
        {module_path},
    )

    if args.pr:
        if not git.bot_working_tree_is_clean():
            raise GitError('unexpected result: git working tree is unclean')

        git.bot_fetch_origin()
        git.bot_force_push_with_lease_to_origin(pr.head.branch)

        pr.create_or_update()

        raise SuccessMessage(pr.info['html_url'])

    if args.export_patches:
        git.bot_patches(starting_point, args.export_patches)

    if args.export_pr_body:
        args.export_pr_body.parent.mkdir(parents=True, exist_ok=True)
        args.export_pr_body.with_suffix('.md').write_text(pr.body)

    if args.export_commit_message:
        args.export_commit_message.parent.mkdir(parents=True, exist_ok=True)
        args.export_commit_message.with_suffix('.txt').write_text(pr.commit_message)

    print(pull_request_body)


def run(args: argparse.Namespace) -> int:
    try:
        _real_run(args)
    except SuccessMessage as message:
        if os.getenv('GITHUB_ACTIONS'):
            print(f'::notice::{message}')
        else:
            print(message, file=sys.stderr)
        return 0
    except BotError as error:
        if os.getenv('GITHUB_ACTIONS'):
            print(f'::error::{error}')
        else:
            print(f'ERROR: {error}', file=sys.stderr)
        return 1

    return 0


if __name__ == '__main__':
    try:
        parser = argparse.ArgumentParser()
        configure_parser(parser)
        sys.exit(run(parser.parse_args()))
    except KeyboardInterrupt:
        print('\nERROR: interrupted by user', file=sys.stderr)
        sys.exit(1)

from __future__ import annotations

import dataclasses
import os
import pathlib
import re
import shlex
import shutil
import subprocess
import sys

from bot.knowledge import GIT_FORGES
from bot.utils import BotError, remove_around


class GitError(BotError):
    pass


@dataclasses.dataclass(frozen=True)
class Commit:
    sha: str
    author_name: str
    author_email: str
    timestamp: int
    message: str
    subject: str
    body: str


class Git:
    _SUPPORTED_PROTOCOLS = ('ssh', 'https')

    def __init__(
        self,
        /,
        repo_path: pathlib.Path,
        *,
        protocol: str | None = None,
        origin_name: str | None = None,
        upstream_name: str | None = None,
        verbose: bool = False,
    ):
        self.repo_path = pathlib.Path(repo_path).expanduser().resolve()
        self.repo_path.mkdir(parents=True, exist_ok=True)

        exe_location = shutil.which('git')
        if not exe_location:
            raise GitError('git executable could not be found')
        if not os.access(exe_location, os.F_OK | os.X_OK) or os.path.isdir(exe_location):
            raise GitError(f'unable to execute {exe_location!r}')

        self._exe: str = exe_location
        self._base_args: list[str] = ['-C', str(self.repo_path)]
        self.verbose = verbose

        if not self.bot_version().startswith('git '):
            raise GitError(f'invalid output from {self._exe}')

        if protocol:
            if protocol not in self._SUPPORTED_PROTOCOLS:
                raise ValueError(f'{protocol} is not a supported git protocol')
            self.protocol = protocol
        else:
            self.protocol = self._determine_protocol()

        self._origin_name = origin_name
        self._upstream_name = upstream_name

    def _determine_protocol(self, /) -> str:
        def any_remote_startswith(prefix: str) -> bool:
            return any(
                remote.rpartition(' ')[2].startswith(prefix)
                for remote in self.bot_config_re_search(r'remote\.[^.]+\.url')
            )

        if any_remote_startswith('git@'):
            return 'ssh'

        if any_remote_startswith('https://'):
            return 'https'

        return 'ssh'

    def _git(self, /, *args: str) -> list[str]:
        null = False

        for arg in args:
            if arg == '--null':
                null = True
                break
            if arg == '--':
                break

        cmd = [self._exe, *self._base_args, *args]
        if self.verbose:
            print(f'[git] {shlex.join(cmd)}', file=sys.stderr)

        try:
            output = subprocess.check_output(cmd, text=True)
        except subprocess.CalledProcessError as error:
            raise GitError(error)

        if null:
            return output.split('\x00')
        return output.splitlines()

    # Basic low-level git operations

    def add(self, /, *args: str) -> list[str]:
        return self._git('add', *args)

    def apply(self, /, *args: str) -> list[str]:
        return self._git('apply', *args)

    def branch(self, /, *args: str) -> list[str]:
        return self._git('branch', *args)

    def checkout(self, /, *args: str) -> list[str]:
        return self._git('checkout', *args)

    def cherry(self, /, *args: str) -> list[str]:
        return self._git('cherry', *args)

    def cherry_pick(self, /, *args: str) -> list[str]:
        return self._git('cherry-pick', *args)

    def clone(self, /, *args: str) -> list[str]:
        return self._git('clone', *args)

    def commit(self, /, *args: str) -> list[str]:
        return self._git('commit', *args)

    def config(self, /, *args: str) -> list[str]:
        return self._git('config', *args)

    def diff(self, /, *args: str) -> list[str]:
        return self._git('diff', *args)

    def fetch(self, /, *args: str) -> list[str]:
        return self._git('fetch', *args)

    def format_patch(self, /, *args: str) -> list[str]:
        return self._git('format-patch', *args)

    def init(self, /, *args: str) -> list[str]:
        return self._git('init', *args)

    def log(self, /, *args: str) -> list[str]:
        return self._git('log', *args)

    def merge(self, /, *args: str) -> list[str]:
        return self._git('merge', *args)

    def mv(self, /, *args: str) -> list[str]:
        return self._git('mv', *args)

    def pull(self, /, *args: str) -> list[str]:
        return self._git('pull', *args)

    def push(self, /, *args: str) -> list[str]:
        return self._git('push', *args)

    def rebase(self, /, *args: str) -> list[str]:
        return self._git('rebase', *args)

    def remote(self, /, *args: str) -> list[str]:
        return self._git('remote', *args)

    def reset(self, /, *args: str) -> list[str]:
        return self._git('reset', *args)

    def restore(self, /, *args: str) -> list[str]:
        return self._git('restore', *args)

    def rev_parse(self, /, *args: str) -> list[str]:
        return self._git('rev-parse', *args)

    def revert(self, /, *args: str) -> list[str]:
        return self._git('revert', *args)

    def rm(self, /, *args: str) -> list[str]:
        return self._git('rm', *args)

    def version(self, /, *args) -> list[str]:
        return self._git('version', *args)

    # Higher-level methods (`bot_`-prefixed)

    def bot_version(self, /) -> str:
        return self.version()[0]

    def bot_rev_parse(self, /, revision: str) -> str:
        if result := self.rev_parse(revision):
            return result[0]
        raise GitError(f'git command failed to return a value: git rev-parse -- {revision}')

    def bot_current_branch(self, /) -> str:
        if result := self.branch('--show-current'):
            return result[0]
        raise GitError('git command failed to return a value: git branch --show-current')

    def bot_working_tree_is_clean(self, /) -> bool:
        return not self.diff('--name-only') and not self.diff('--name-only', '--cached')

    def bot_overwrite_branch(self, /, target_branch: str, start_point: str) -> None:
        if self.bot_current_branch() == target_branch:
            self.checkout(self.bot_rev_parse('HEAD'))
        self.checkout('-B', target_branch, start_point)

    def bot_config_re_search(self, /, pattern: str) -> list[str]:
        try:
            return self.config('--null', '--get-regexp', pattern)
        except GitError:
            return []

    def bot_get_remote_by_url(self, /, remote_url: str) -> str | None:
        for remote in self.bot_config_re_search(r'remote\.[^.]+\.url'):
            setting, _, url = remote.partition(' ')
            if url.strip() == remote_url:
                return remove_around(setting.strip(), 'remote.', '.url')

        return None

    def bot_check_if_remote_exists(self, /, remote_name: str) -> bool:
        return bool(self.bot_config_re_search(re.escape(f'remote.{remote_name}.url')))

    def bot_make_remote_url(self, /, forge: str, owner: str, repo: str) -> str:
        forge = forge.lower()
        if forge not in GIT_FORGES:
            raise ValueError(f'unsupported git forge: {forge}')

        templates = GIT_FORGES[forge]['remote_url_templates']
        if self.protocol not in templates:
            raise ValueError(f'unsupported protcol for {forge} forge: {self.protocol}')

        return templates[self.protocol].format(owner=owner, repo=repo)

    def bot_get_remote_url(self, /, remote_name: str, *, push: bool = False) -> str:
        git_args = ['get-url', '--push' if push else '--no-push', '--', remote_name]
        try:
            return self.remote(*git_args)[0]
        except (GitError, IndexError):
            raise GitError(f'unable to get remote URL for "{remote_name}"')

    def bot_add_or_verify_remote(
        self,
        /,
        remote_name: str,
        forge: str,
        owner: str,
        repo: str,
        *,
        push: bool = False,
    ) -> None:
        remote_url = self.bot_make_remote_url(forge, owner, repo)
        if not self.bot_check_if_remote_exists(remote_name):
            self.remote('add', '--', remote_name, remote_url)
            return

        actual_remote_url = self.bot_get_remote_url(remote_name, push=push)
        if actual_remote_url in (remote_url, remote_url.removesuffix('.git')):
            return

        raise GitError(
            f'"{remote_name}" ({"push" if push else "fetch"}): expected {remote_url!r}, got {actual_remote_url!r}'
        )

    def bot_clone_upstream_here(self, /, forge: str, owner: str, repo: str) -> None:
        if not self._upstream_name:
            raise ValueError('an upstream remote was not configured')

        upstream_url = self.bot_make_remote_url(forge, owner, repo)
        self.clone('--origin', self._upstream_name, upstream_url, str(self.repo_path))

    def bot_fetch_upstream(self, /) -> list[str]:
        if not self._upstream_name:
            raise ValueError('an upstream remote was not configured')

        return self.fetch('--no-tags', '--', self._upstream_name)

    def bot_fetch_origin(self, /) -> list[str]:
        if not self._origin_name:
            raise ValueError('an origin remote was not configured')

        return self.fetch('--no-tags', '--', self._origin_name)

    def bot_force_push_with_lease_to_origin(self, /, refspec: str) -> list[str]:
        if not self._origin_name:
            raise ValueError('an origin remote was not configured')

        return self.push('--force-with-lease', '--', self._origin_name, refspec)

    def bot_commit(
        self,
        /,
        commit_message: str,
        updated_paths: set[pathlib.Path],
    ) -> list[str]:
        self.add('--', *map(str, updated_paths))
        return self.commit('-m', commit_message)

    def bot_patches(
        self,
        /,
        since_or_range: str,
        output_dir: str | pathlib.Path | None = None,
    ) -> list[str]:
        git_args = ['--keep-subject']
        if output_dir:
            git_args.extend([
                '--output-directory',
                str(pathlib.Path(output_dir).resolve()),
            ])

        return self.format_patch(*git_args, since_or_range)

    def bot_get_commit_subject(self, /, revision: str) -> str:
        git_args = ['--format=%s', f'{revision}^-']
        if result := self.log(*git_args):
            return result[0]
        raise GitError(f'git command failed to return a value: git log {shlex.join(git_args)}')

    def bot_get_commit(self, /, revision: str) -> Commit:
        def get_field(field: str) -> list[str]:
            return self.log(f'--format=%{field}', f'{revision}^-')

        try:
            return Commit(
                sha=get_field('H')[0],
                author_name=get_field('aN')[0],
                author_email=get_field('aE')[0],
                timestamp=int(get_field('at')[0]),
                message='\n'.join(get_field('B')),
                subject=get_field('s')[0],
                body='\n'.join(get_field('b')),
            )
        except (AttributeError, IndexError, TypeError, ValueError):
            raise GitError(f'unable to get commit info for "{revision}"')

    def bot_list_new_commits(self, /, base: str, *, head: str | None = None) -> list[Commit]:
        commits = []
        git_args = list(filter(None, ['--', base, head]))
        for line in self.cherry(*git_args):
            if line.startswith('+'):
                commits.append(self.bot_get_commit(line.removeprefix('+').strip()))

        return commits

from __future__ import annotations

import collections.abc
import dataclasses
import datetime as dt
import itertools
import json
import os
import pathlib
import re
import sys
import time
import types
import typing

from bot.utils import (
    BaseAPICaller,
    BotError,
    filter_dict,
)

GITHUB_URL_RE = re.compile(r'https://github\.com/(?!sponsors/)(?P<owner>[0-9a-zA-Z_-]+)/(?P<repo>[0-9a-zA-Z_-]+)')


class GitHubError(BotError):
    pass


@dataclasses.dataclass(frozen=True)
class BaseBranch:
    __slots__ = ()

    def __new__(cls, *args, **kwargs):
        if cls == BaseBranch:
            raise TypeError('cannot instantiate base class')
        return super().__new__(cls)

    def __post_init__(self):
        for slot in self.__slots__:
            value = getattr(self, slot)
            if not isinstance(value, str):
                raise TypeError(f'{type(self).__name__}.{slot} expects a string, got {type(value).__name__!r}')
            if not value:
                raise ValueError(f'{type(self).__name__}.{slot} value cannot be empty')

    def __str__(self):
        return f'{self.owner}:{self.branch}'

    @property
    def label(self, /):
        return str(self)


@dataclasses.dataclass(frozen=True)
class RelativeBranch(BaseBranch):
    __slots__ = ('branch', 'owner')

    owner: str
    branch: str


@dataclasses.dataclass(frozen=True)
class AbsoluteBranch(BaseBranch):
    # GitHub supports this label pattern since 2024
    # Ref: https://github.com/github/docs/issues/34381
    __slots__ = ('branch', 'owner', 'repo')

    owner: str
    repo: str
    branch: str

    @property
    def full_label(self, /):
        return f'{self.owner}:{self.repo}:{self.branch}'


def parse_branch_compare_label(label: str) -> tuple[str, str | None, str]:
    # "branch compare label" is our name for the labels GitHub uses when comparing across forks
    # e.g. yt-dlp:master...bashonly:feature
    # https://docs.github.com/en/rest/commits/commits?apiVersion=2026-03-10#compare-two-commits
    owner, _, repo_and_branch = label.partition(':')
    repo, _, branch = repo_and_branch.rpartition(':')
    return owner, repo or None, branch


def make_absolute_branch(label: str, repo: str | None = None) -> AbsoluteBranch:
    owner, parsed_repo, branch = parse_branch_compare_label(label)
    repo = parsed_repo or repo
    if not repo or not isinstance(repo, str):
        raise ValueError('make_absolute_branch requires a repo value')

    return AbsoluteBranch(owner=owner, repo=repo, branch=branch)


class GitHubAPICaller(BaseAPICaller):
    _API_BASE_URL = 'https://api.github.com/'
    _NOTE_PREFIX = 'api'

    def __init__(
        self,
        /,
        *,
        retries: int = 3,
        timeout: int = 5,
        verbose: bool = False,
        user_agent: str = 'dlp-bot',
        github_token: str | None = None,
    ):
        super().__init__(
            base_url=self._API_BASE_URL,
            retries=retries,
            timeout=timeout,
            verbose=verbose,
            user_agent=user_agent,
            note_prefix=self._NOTE_PREFIX,
            custom_exception=GitHubError,
        )
        self._github_token = [REDACTED]

    @property
    def headers(self) -> dict[str, str]:
        return filter_dict({
            **super().headers,
            'Accept': 'application/vnd.github+json',
            'Authorization': f'Bearer {self._github_token}' if self._github_token else None,
            'X-GitHub-Api-Version': '2026-03-10',
        })

    def call(
        self,
        /,
        path: str,
        *,
        query: dict[str, str | None] | None = None,
        body: dict[str, str | bool | int | float] | None = None,
        headers: dict[str, str] | None = None,
        method: str | None = None,
        status_check: list[int] | None = None,
    ):
        return self._fetch_json(
            path,
            query=query,
            data=json.dumps(body, separators=(',', ':')).encode() if body else None,
            headers=filter_dict({
                **self.headers,
                'Content-Type': 'application/json' if body else None,
                **(headers or {}),
            }),
            method=method,
            status_check=status_check,
        )

    def paginator(
        self,
        /,
        func: types.MethodType,
        *args: str,
        searches: list[dict[str, str | bool | int | float | list]] | None = None,
        **kwargs: str | bool | None,
    ) -> collections.abc.Iterator[dict[str, typing.Any]]:
        """Yield pages from any GithubAPICaller.list_* method

        `searches` is a list of dicts with key/value pairs to filter the results by.
        The generator will yield matches until all searches are found or result pages are exhausted.
        If a `searches` dict value is a list, it works like a logical OR for its contained values.
        """
        func_name = func.__name__
        assert func_name.startswith('list_'), f'{func_name} does not return a list'
        assert hasattr(func, '__self__'), f'{func_name} is not an instance method'
        assert isinstance(func.__self__, GitHubAPICaller), f'cannot use {func_name} with paginator'

        if searches:
            requirements = searches.copy()
        else:
            requirements = []

        def filter_func(
            filter_pairs: dict[str, str | bool | int | float | list],
        ) -> collections.abc.Callable[[dict[str, typing.Any]], bool]:
            def inner_func(
                input_dict: dict[str, typing.Any],
            ) -> bool:
                if all(
                    input_dict.get(k) in v if isinstance(v, list) else input_dict.get(k) == v
                    for k, v in filter_pairs.items()
                ):
                    if filter_pairs in requirements:
                        requirements.remove(filter_pairs)
                    return True
                return False

            return inner_func

        for page in itertools.count(1):
            kwargs['page'] = str(page)
            results = func(*args, **kwargs)
            if not results:
                return

            if searches:
                for search in searches:
                    yield from filter(filter_func(search), results)
                if not requirements:
                    return
            else:
                yield from results

    def paginated_results(
        self,
        /,
        *args,
        **kwargs,
    ) -> list[dict[str, typing.Any]]:
        return list(self.paginator(*args, **kwargs))

    # Repositories: https://docs.github.com/en/rest/repos/repos?apiVersion=2026-03-10

    def get_repository(self, /, owner: str, repo: str):
        """Get a repository

        Ref: https://docs.github.com/en/rest/repos/repos?apiVersion=2026-03-10#get-a-repository

        @param owner:                   repository owner
        @param repo:                    repository name
