    def get_tag_by_name(self, /, owner: str, repo: str, tag_name: str):
        """Get a tag (by name)

        @param owner:                   repository owner
        @param repo:                    repository name
        @param tag_name:                tag name
        @returns                        dict of info about the tag if found or False if not found
